# LocGuard

## Purpose

LocGuard is a first-party CLI for enforcing source metrics without PHPMD. It checks PHP files for physical file length, file NCLOC, class-like length, function length, method length, and cyclomatic complexity.

## Command

Run:

```bash
vendor/bin/loc-guard --config=loc.yaml
```

Exit codes:

- `0`: no violations
- `1`: metric violations found
- `2`: configuration or runtime error

## Configuration

Example `loc.yaml`:

```yaml
paths:
  - src

exclude: []

limits:
  max_file_lines: 500
  max_file_ncloc: 350
  max_class_lines: 400
  max_trait_lines: 300
  max_interface_lines: 200
  max_enum_lines: 200
  max_function_lines: 50
  max_method_lines: 50
  max_cyclomatic_complexity: 20

report:
  reporter: ai
  order_by:
    - path
    - line
    - rule
```

The limit value itself is allowed. A method with exactly 50 lines passes when `max_method_lines` is `50`; a method with 51 lines fails.

## Metrics

`max_file_lines` counts physical lines exactly as stored on disk.

`max_file_ncloc` counts non-comment lines of PHP code. Blank lines, comments, doc comments, and PHP open/close tags are excluded.

`max_class_lines`, `max_trait_lines`, `max_interface_lines`, and `max_enum_lines` count physical lines from the class-like declaration line through its closing brace.

## Analysis Scope

Use production source roots only. Do not include `tests/` by default; test method and fixture length are intentionally out of scope.

`exclude` entries are glob patterns relative to the config directory:

```yaml
exclude:
  - 'src/Generated/*'
```

## Complexity

LocGuard starts each function or method at complexity `1` and increments for branch points such as `if`, `elseif`, loops, `case`, `catch`, boolean operators, null coalescing, ternary branches, and `match` arms.

## Reporting

Configure the reporter with `report.reporter`:

- `ai`: structured text with remediation guidance for coding agents.
- `text`: concise human-readable output.
- `json`: machine-readable JSON for CI and tooling.

Override the configured reporter from the CLI:

```bash
vendor/bin/loc-guard --config=loc.yaml --reporter=json
vendor/bin/loc-guard --config=loc.yaml --format=text
```

Configure violation ordering with `report.order_by`. Supported fields are `path`, `line`, `rule`, `actual`, and `limit`.
<?php

declare(strict_types=1);

namespace Toolkit\LocGuard\Config;

use function dirname;
use function is_array;
use function is_file;
use function sprintf;

use Symfony\Component\Yaml\Exception\ParseException;
use Symfony\Component\Yaml\Yaml;
use Toolkit\LocGuard\LocGuardException;

/**
 * Loads and validates loc.yaml.
 */
final class ConfigLoader
{
    /** @readonly */
    private ConfigStringListReader $stringListReader;

    /** @readonly */
    private LimitConfigReader $limitConfigReader;

    /** @readonly */
    private ReportConfigReader $reportConfigReader;

    /**
     * Creates a config loader from YAML section readers.
     */
    public function __construct(
        ?ConfigStringListReader $stringListReader = null,
        ?LimitConfigReader $limitConfigReader = null,
        ?ReportConfigReader $reportConfigReader = null,
    ) {
        $this->stringListReader = $stringListReader ?? new ConfigStringListReader();
        $this->limitConfigReader = $limitConfigReader ?? new LimitConfigReader();
        $this->reportConfigReader = $reportConfigReader ?? new ReportConfigReader();
    }

    /**
     * Loads and validates a LocGuard YAML configuration file.
     *
     * @throws LocGuardException when the file is missing, unparsable, or not a mapping
     */
    public function load(string $path): LocGuardConfig
    {
        if (!is_file($path)) {
            throw new LocGuardException(sprintf('LocGuard config not found: %s', $path));
        }

        try {
            $data = Yaml::parseFile($path);
        } catch (ParseException $exception) {
            throw new LocGuardException('Invalid loc.yaml: ' . $exception->getMessage(), 0, $exception);
        }

        if (!is_array($data)) {
            throw new LocGuardException('Invalid loc.yaml: top-level value must be a mapping.');
        }

        return new LocGuardConfig(
            dirname($path),
            $this->stringListReader->read($data, 'paths', ['src']),
            $this->stringListReader->read($data, 'exclude', []),
            $this->limitConfigReader->read($data['limits'] ?? []),
            $this->reportConfigReader->read($data['report'] ?? []),
        );
    }
}
<?php

declare(strict_types=1);

namespace Toolkit\LocGuard\Config;

/**
 * Fully resolved LocGuard configuration.
 *
 * @property-read string $root
 * @property-read list<string> $paths
 * @property-read list<string> $exclude
 * @property-read LimitConfig $limits
 * @property-read ReportConfig $report
 */
final class LocGuardConfig
{
    /**
     * @param list<string> $paths
     * @param list<string> $exclude
     */
    public function __construct(
        /** @readonly */
        private string $root,
        /** @readonly */
        private array $paths,
        /** @readonly */
        private array $exclude,
        /** @readonly */
        private LimitConfig $limits,
        /** @readonly */
        private ReportConfig $report,
    ) {
    }

    /**
     * Provides read-only access to the immutable properties.
     *
     * @return mixed the value of the requested property
     */
    public function __get(string $name): mixed
    {
        return match ($name) {
            'root' => $this->root,
            'paths' => $this->paths,
            'exclude' => $this->exclude,
            'limits' => $this->limits,
            'report' => $this->report,
            default => null,
        };
    }
}
<?php

declare(strict_types=1);

namespace Toolkit\LocGuard\Config;

/**
 * Numeric thresholds used by LocGuard.
 *
 * @property-read int $maxFileLines
 * @property-read int $maxFileNcloc
 * @property-read int $maxClassLines
 * @property-read int $maxTraitLines
 * @property-read int $maxInterfaceLines
 * @property-read int $maxEnumLines
 * @property-read int $maxFunctionLines
 * @property-read int $maxMethodLines
 * @property-read int $maxCyclomaticComplexity
 */
final class LimitConfig
{
    /**
     * Creates line-count and cyclomatic complexity thresholds.
     */
    public function __construct(
        /** @readonly */
        private int $maxFileLines,
        /** @readonly */
        private int $maxFileNcloc,
        /** @readonly */
        private int $maxClassLines,
        /** @readonly */
        private int $maxTraitLines,
        /** @readonly */
        private int $maxInterfaceLines,
        /** @readonly */
        private int $maxEnumLines,
        /** @readonly */
        private int $maxFunctionLines,
        /** @readonly */
        private int $maxMethodLines,
        /** @readonly */
        private int $maxCyclomaticComplexity,
    ) {
    }

    /**
     * Provides read-only access to the immutable properties.
     *
     * @return mixed the value of the requested property
     */
    public function __get(string $name): mixed
    {
        return match ($name) {
            'maxFileLines' => $this->maxFileLines,
            'maxFileNcloc' => $this->maxFileNcloc,
            'maxClassLines' => $this->maxClassLines,
            'maxTraitLines' => $this->maxTraitLines,
            'maxInterfaceLines' => $this->maxInterfaceLines,
            'maxEnumLines' => $this->maxEnumLines,
            'maxFunctionLines' => $this->maxFunctionLines,
            'maxMethodLines' => $this->maxMethodLines,
            'maxCyclomaticComplexity' => $this->maxCyclomaticComplexity,
            default => null,
        };
    }
}
<?php

declare(strict_types=1);

namespace Toolkit\LocGuard\Config;

use function is_array;

use Toolkit\LocGuard\LocGuardException;

/**
 * Reads LocGuard numeric limits from loc.yaml.
 */
final class LimitConfigReader
{
    /** @readonly */
    private ConfigScalarReader $scalarReader;

    /**
     * Creates a reader from scalar validation.
     */
    public function __construct(?ConfigScalarReader $scalarReader = null)
    {
        $this->scalarReader = $scalarReader ?? new ConfigScalarReader();
    }

    /**
     * Reads line-count and complexity limits.
     *
     * @param mixed $value
     *
     * @throws LocGuardException when the limits section is not a mapping
     */
    public function read($value): LimitConfig
    {
        if (!is_array($value)) {
            throw new LocGuardException('Invalid loc.yaml: "limits" must be a mapping.');
        }

        return new LimitConfig(
            $this->scalarReader->positiveInt($value, 'max_file_lines', 500),
            $this->scalarReader->positiveInt($value, 'max_file_ncloc', 350),
            $this->scalarReader->positiveInt($value, 'max_class_lines', 400),
            $this->scalarReader->positiveInt($value, 'max_trait_lines', 300),
            $this->scalarReader->positiveInt($value, 'max_interface_lines', 200),
            $this->scalarReader->positiveInt($value, 'max_enum_lines', 200),
            $this->scalarReader->positiveInt($value, 'max_function_lines', 50),
            $this->scalarReader->positiveInt($value, 'max_method_lines', 50),
            $this->scalarReader->positiveInt($value, 'max_cyclomatic_complexity', 20),
        );
    }
}
<?php

declare(strict_types=1);

namespace Toolkit\LocGuard\Filesystem;

use function fnmatch;
use function str_ends_with;

use Toolkit\LocGuard\Config\LocGuardConfig;

/**
 * Decides whether a discovered file belongs in LocGuard analysis.
 */
final class PhpFileInclusionPolicy
{
    /** @readonly */
    private LocGuardPathResolver $pathResolver;

    /**
     * Creates an inclusion policy from path resolution.
     */
    public function __construct(?LocGuardPathResolver $pathResolver = null)
    {
        $this->pathResolver = $pathResolver ?? new LocGuardPathResolver();
    }

    /**
     * Reports whether the path is a non-excluded PHP file.
     */
    public function includes(LocGuardConfig $config, string $path): bool
    {
        $relativePath = $this->pathResolver->relative($config->root, $path);
        if (!str_ends_with($relativePath, '.php')) {
            return false;
        }

        foreach ($config->exclude as $pattern) {
            if (fnmatch($pattern, $relativePath)) {
                return false;
            }
        }

        return true;
    }
}
<?php

declare(strict_types=1);

namespace Toolkit\LocGuard\Filesystem;

use function is_dir;
use function is_file;

use RecursiveDirectoryIterator;
use RecursiveIteratorIterator;
use SplFileInfo;

use function sprintf;

use Toolkit\LocGuard\Config\LocGuardConfig;
use Toolkit\LocGuard\LocGuardException;

/**
 * Collects PHP files from one configured absolute path.
 */
final class PhpPathFileCollector
{
    /** @readonly */
    private PhpFileInclusionPolicy $inclusionPolicy;

    /** @readonly */
    private LocGuardPathResolver $pathResolver;

    /**
     * Creates a collector from inclusion and path resolution policies.
     */
    public function __construct(
        ?PhpFileInclusionPolicy $inclusionPolicy = null,
        ?LocGuardPathResolver $pathResolver = null,
    ) {
        $this->inclusionPolicy = $inclusionPolicy ?? new PhpFileInclusionPolicy();
        $this->pathResolver = $pathResolver ?? new LocGuardPathResolver();
    }

    /**
     * Returns PHP files under the configured path.
     *
     * @return array<string, string>
     *
     * @throws LocGuardException when the configured path does not exist
     */
    public function files(LocGuardConfig $config, string $path): array
    {
        if (is_file($path)) {
            return $this->inclusionPolicy->includes($config, $path) ? [$path => $this->pathResolver->relative($config->root, $path)] : [];
        }

        if (!is_dir($path)) {
            throw new LocGuardException(sprintf('Configured path does not exist: %s', $path));
        }

        $files = [];
        $iterator = new RecursiveIteratorIterator(
            new RecursiveDirectoryIterator($path, RecursiveDirectoryIterator::SKIP_DOTS),
        );

        /** @var SplFileInfo $item */
        foreach ($iterator as $item) {
            $file = $item->getPathname();
            if ($this->inclusionPolicy->includes($config, $file)) {
                $files[$file] = $this->pathResolver->relative($config->root, $file);
            }
        }

        return $files;
    }
}
<?php

declare(strict_types=1);

namespace Toolkit\LocGuard\Filesystem;

use function rtrim;
use function str_replace;
use function strlen;
use function substr;

/**
 * Resolves absolute and project-relative paths for LocGuard file scanning.
 */
final class LocGuardPathResolver
{
    /**
     * Returns an absolute path for a configured source path.
     */
    public function absolute(string $root, string $path): string
    {
        if (str_starts_with($path, '/')) {
            return rtrim($path, '/');
        }

        return rtrim($root . '/' . $path, '/');
    }

    /**
     * Returns a path relative to the LocGuard project root when possible.
     */
    public function relative(string $root, string $path): string
    {
        $root = rtrim(str_replace('\\', '/', $root), '/') . '/';
        $path = str_replace('\\', '/', $path);

        return str_starts_with($path, $root) ? substr($path, strlen($root)) : $path;
    }
}

