    /** @readonly */
    private PhpFileAnalyzer $fileAnalyzer;

    /**
     * Creates an analyzer with injectable file discovery and per-file analysis.
     */
    public function __construct(
        ?PhpFileFinder $fileFinder = null,
        ?PhpFileAnalyzer $fileAnalyzer = null,
    ) {
