        file_put_contents($file, <<<'PHP'
<?php

class Example
{
}

trait Behavior
{
}

interface Contract
{
}

enum Status
{
    case Open;
}
PHP);

        $analysis = (new PhpFileAnalyzer())->analyze(
            $file,
            'src/Types.php',
            new LimitConfig(100, 100, 2, 2, 2, 2, 50, 50, 20),
        );

