+<?php
+
+declare(strict_types=1);
+
+namespace Tests\Unit\LocGuard;
+
+use Toolkit\LocGuard\Config\ApplyConfig;
+use Toolkit\LocGuard\Config\LimitConfig;
+use Toolkit\LocGuard\Config\LocGuardConfig;
+use Toolkit\LocGuard\Config\PolicyConfig;
+use Toolkit\LocGuard\Config\ReportConfig;
+use Toolkit\LocGuard\Config\ScanConfig;
+
+/**
+ * Creates complete LocGuard configuration for focused unit tests.
+ */
+final class LocGuardTestConfig
+{
+    /**
+     * @param list<string> $roots
+     * @param list<string> $exclude
+     */
+    public static function create(
+        string $root,
+        array $roots,
+        array $exclude,
+        LimitConfig $limits,
+        ReportConfig $report,
+    ): LocGuardConfig {
+        return new LocGuardConfig(
+            $root,
+            new ScanConfig($roots, $exclude),
+            ['standard' => new PolicyConfig('standard', null, $limits)],
+            new ApplyConfig('standard', []),
+            $report,
+        );
+    }
+}
*** End Patch";
text(await tools.apply_patch(patch));

