<?php

declare(strict_types=1);

namespace Toolkit\LocGuard\Config;

use function array_values;
use function implode;
use function is_array;
use function sprintf;

use Toolkit\LocGuard\LocGuardException;

/**
 * Reads and validates policy application configuration.
 */
final class ApplyConfigReader
{
    /** @readonly */
    private ConfigKeyValidator $keyValidator;

    /** @readonly */
    private ConfigScalarReader $scalarReader;

    /** @readonly */
    private ApplyRuleConfigReader $ruleConfigReader;

    /**
     * Creates an apply reader from mapping, scalar, and rule validation.
     */
    public function __construct(
        ?ConfigKeyValidator $keyValidator = null,
        ?ConfigScalarReader $scalarReader = null,
        ?ApplyRuleConfigReader $ruleConfigReader = null,
    ) {
        $this->keyValidator = $keyValidator ?? new ConfigKeyValidator();
        $this->scalarReader = $scalarReader ?? new ConfigScalarReader();
        $this->ruleConfigReader = $ruleConfigReader ?? new ApplyRuleConfigReader();
    }

    /**
     * Reads default and path-specific policy assignments.
     *
     * @param mixed $value
     * @param array<string, PolicyConfig> $policies
     *
     * @throws LocGuardException when assignments are invalid
     */
    public function read($value, array $policies): ApplyConfig
    {
        if (!is_array($value)) {
            throw new LocGuardException('Invalid loc.yaml: "apply" must be a mapping.');
        }
        $this->keyValidator->rejectUnknown($value, ['default', 'rules'], 'apply');

        $defaultPolicy = $this->scalarReader->requiredString($value, 'default', 'apply');
        $rulesValue = $value['rules'] ?? [];
        if (!is_array($rulesValue) || array_values($rulesValue) !== $rulesValue) {
            throw new LocGuardException('Invalid loc.yaml: "apply.rules" must be a list of mappings.');
        }

        $rules = [];
        $ruleNames = [];
        foreach ($rulesValue as $index => $ruleValue) {
            $rule = $this->ruleConfigReader->read($ruleValue, $index);
            if (isset($ruleNames[$rule->name])) {
                throw new LocGuardException(sprintf('Invalid loc.yaml: duplicate apply rule name "%s".', $rule->name));
            }
            $ruleNames[$rule->name] = true;
            $rules[] = $rule;
        }

        $referenced = [$defaultPolicy => true];
        foreach ($rules as $rule) {
            $referenced[$rule->policy] = true;
        }
        foreach ($referenced as $policy => $used) {
            if (!isset($policies[$policy])) {
                throw new LocGuardException(sprintf('Invalid loc.yaml: apply references unknown policy "%s".', $policy));
            }
        }

        $pending = array_keys($referenced);
        foreach ($pending as $policy) {
            $parent = $policies[$policy]->extends;
            if ($parent !== null && !isset($referenced[$parent])) {
                $referenced[$parent] = true;
                $pending[] = $parent;
            }
        }

        $unused = [];
        foreach ($policies as $name => $policy) {
            if (!isset($referenced[$name])) {
                $unused[] = $name;
            }
        }
        if ($unused !== []) {
            throw new LocGuardException(sprintf(
                'Invalid loc.yaml: unused policies: %s. Assign or remove them.',
                implode(', ', $unused),
            ));
        }

        return new ApplyConfig($defaultPolicy, $rules);
    }
}

